WITH sequenced AS (SELECT mktcode,tgtcode,bizdate,volume,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate DESC) AS seq FROM `newzl`.`hsj_stock_hq_basic`), daily AS (SELECT mktcode,tgtcode,bizdate,MAX(volume) AS value FROM sequenced WHERE seq<=15 GROUP BY mktcode,tgtcode,bizdate), ranked AS (SELECT mktcode,tgtcode,bizdate,ROW_NUMBER() OVER(PARTITION BY bizdate ORDER BY value DESC,mktcode,tgtcode) AS rn,COUNT(*) OVER(PARTITION BY bizdate) AS population FROM daily), marked AS (SELECT *,CASE WHEN rn>=CEIL(population*5/100.0) AND rn<=CEIL(population*10/100.0) THEN 1 ELSE 0 END AS matched FROM ranked), all_rows AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS all_seq FROM marked), hits AS (SELECT mktcode,tgtcode,bizdate,all_seq,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS hit_seq FROM all_rows WHERE matched=1), runs AS (SELECT mktcode,tgtcode,all_seq-hit_seq AS grp,COUNT(*) AS run_length FROM hits GROUP BY mktcode,tgtcode,all_seq-hit_seq), qualified AS (SELECT mktcode,tgtcode FROM runs GROUP BY mktcode,tgtcode HAVING MAX(run_length)>=3) SELECT a.mktcode,a.tgtcode,a.bizdate FROM (SELECT mktcode,tgtcode,bizdate,volume,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14') a JOIN qualified q ON q.mktcode=a.mktcode AND q.tgtcode=a.tgtcode;
